		component: "icon",
		demo: "inherited-from-a-button",
		title: "Inherited from a Button",
		description: "Size and colour are inherited, not passed. A `Button` publishes its own step on the shared scale and its variant's foreground token, so a bare `Icon` composed into it comes out right with nothing said at the call site — no `startIcon` prop, and no colour repeated here.",
		frame: "stage",
		width: 720,
		height: 530,
		animated: false,
		code: "import { BUTTON_SIZES, Button } from \"@delacour/native-ui/button\";\nimport { Icon } from \"@delacour/native-ui/icon\";\nimport { IconBookmark } from \"@delacour/native-ui/icons/central\";\nimport type { ReactElement } from \"react\";\nimport { View } from \"react-native\";\n\nconst VARIANTS = [\"primary\", \"secondary\", \"outline\", \"danger\"] as const;\n\nexport function Demo(): ReactElement {\n\treturn (\n\t\t<View className=\"gap-3\">\n\t\t\t{BUTTON_SIZES.map((size) => (\n\t\t\t\t<Button key={size} size={size} testID={`bookmark-${size}`}>\n\t\t\t\t\t<Icon icon={IconBookmark} />\n\t\t\t\t\t<Button.Label>size {size}</Button.Label>\n\t\t\t\t</Button>\n\t\t\t))}\n\t\t\t<View className=\"flex-row flex-wrap gap-2\">\n\t\t\t\t{VARIANTS.map((variant) => (\n\t\t\t\t\t<Button key={variant} size=\"sm\" variant={variant}>\n\t\t\t\t\t\t<Icon icon={IconBookmark} />\n\t\t\t\t\t\t<Button.Label>{variant}</Button.Label>\n\t\t\t\t\t</Button>\n\t\t\t\t))}\n\t\t\t</View>\n\t\t</View>\n\t);\n}\n",
