	"screen/anatomy": {
		id: "screen/anatomy",
		component: "screen",
		demo: "anatomy",
		title: "A navbar, a body and a footer",
		description: "The whole composition, and the only one most screens need. Nothing here names a safe-area inset or a navbar height — each part measures itself into the screen context and the scroll area reserves exactly that, so the first row clears the bar and the last one clears the footer.",
		frame: "device",
		width: 332,
		height: 720,
		animated: false,
		code: "import { Button } from \"@delacour/native-ui/button\";\nimport { Icon } from \"@delacour/native-ui/icon\";\nimport { IconMagnifyingGlass, IconSettingsGear1 } from \"@delacour/native-ui/icons/central\";\nimport { ListGroup } from \"@delacour/native-ui/list-group\";\nimport { Screen } from \"@delacour/native-ui/screen\";\nimport { type ReactElement, useState } from \"react\";\nimport { View } from \"react-native\";\n\nconst MESSAGES = [\n\t{ id: \"ada\", title: \"Ada Lovelace\", description: \"The analytical engine has no pretensions\" },\n\t{ id: \"grace\", title: \"Grace Hopper\", description: \"It is easier to ask forgiveness than permission\" },\n\t{ id: \"alan\", title: \"Alan Turing\", description: \"We can only see a short distance ahead\" },\n\t{ id: \"katherine\", title: \"Katherine Johnson\", description: \"Numbers checked, ready when you are\" },\n\t{ id: \"margaret\", title: \"Margaret Hamilton\", description: \"The rope core memory is loaded\" },\n\t{ id: \"barbara\", title: \"Barbara Liskov\", description: \"A subtype should be substitutable\" },\n] as const;\n\n/**\n * A root screen: an overlay navbar, a scrolling body and a footer.\n *\n * There is no back control because a root screen has nowhere to go back to —\n * `Screen.Navbar.BackButton` takes an `onPress` and this library wires no\n * router of its own, so the navigation is the app's to supply.\n *\n * The footer is the part worth watching: it measures its own content into the\n * screen context, and the scroll area reserves that height, so the last row\n * clears it with nothing said at either call site.\n */\nexport function Demo(): ReactElement {\n\tconst [readIds, setReadIds] = useState<string[]>([]);\n\n\tconst unread = MESSAGES.length - readIds.length;\n\n\tfunction markRead(id: string): void {\n\t\tsetReadIds((current) => (current.includes(id) ? current : [...current, id]));\n\t}\n\n\treturn (\n\t\t<Screen>\n\t\t\t<Screen.Navbar\n\t\t\t\tactions={\n\t\t\t\t\t<>\n\t\t\t\t\t\t<Button accessibilityLabel=\"Search\" isIconOnly size=\"sm\" variant=\"secondary\">\n\t\t\t\t\t\t\t<Icon icon={IconMagnifyingGlass} />\n\t\t\t\t\t\t</Button>\n\t\t\t\t\t\t<Button accessibilityLabel=\"Settings\" isIconOnly size=\"sm\" variant=\"secondary\">\n\t\t\t\t\t\t\t<Icon icon={IconSettingsGear1} />\n\t\t\t\t\t\t</Button>\n\t\t\t\t\t</>\n\t\t\t\t}\n\t\t\t>\n\t\t\t\t<View className=\"min-w-0 flex-1\">\n\t\t\t\t\t<Screen.Navbar.Title>Inbox</Screen.Navbar.Title>\n\t\t\t\t\t<Screen.Navbar.Subtitle>{unread === 0 ? \"All caught up\" : `${unread} unread`}</Screen.Navbar.Subtitle>\n\t\t\t\t</View>\n\t\t\t</Screen.Navbar>\n\n\t\t\t<Screen.ScrollArea>\n\t\t\t\t<ListGroup>\n\t\t\t\t\t{MESSAGES.map((message) => (\n\t\t\t\t\t\t<ListGroup.Item key={message.id} onPress={() => markRead(message.id)} testID={`row-${message.id}`}>\n\t\t\t\t\t\t\t<ListGroup.ItemContent>\n\t\t\t\t\t\t\t\t<ListGroup.ItemTitle>{message.title}</ListGroup.ItemTitle>\n\t\t\t\t\t\t\t\t<ListGroup.ItemDescription>\n\t\t\t\t\t\t\t\t\t{readIds.includes(message.id) ? \"Read\" : message.description}\n\t\t\t\t\t\t\t\t</ListGroup.ItemDescription>\n\t\t\t\t\t\t\t</ListGroup.ItemContent>\n\t\t\t\t\t\t\t<ListGroup.ItemSuffix />\n\t\t\t\t\t\t</ListGroup.Item>\n\t\t\t\t\t))}\n\t\t\t\t</ListGroup>\n\t\t\t</Screen.ScrollArea>\n\n\t\t\t<Screen.Footer>\n\t\t\t\t<Button\n\t\t\t\t\thaptic=\"medium\"\n\t\t\t\t\tisDisabled={unread === 0}\n\t\t\t\t\tonPress={() => setReadIds(MESSAGES.map((message) => message.id))}\n\t\t\t\t\ttestID=\"mark-all-read\"\n\t\t\t\t>\n\t\t\t\t\tMark all as read\n\t\t\t\t</Button>\n\t\t\t</Screen.Footer>\n\t\t</Screen>\n\t);\n}\n",
		light: { poster: "/previews/screen/anatomy/light.png?v=c24d6064859f" },
		dark: { poster: "/previews/screen/anatomy/dark.png?v=c24d6064859f" },
		sourceHash: "c24d6064859f",
		capturedAt: "2026-08-26T19:26:50.772Z",
		device: "iPhone 17 Pro · iOS 26.3",
	},
	"screen/loading-and-error": {
		id: "screen/loading-and-error",
		component: "screen",
		demo: "loading-and-error",
		title: "Loading and error",
		description: "The two whole-screen states a route returns instead of its content. Both keep the navbar by default, so the frame does not jump when the real content replaces them and a user is never stranded on a screen they cannot leave — `showNavbar={false}` drops it for a root screen with nowhere to go back to.",
		frame: "device",
		width: 332,
		height: 720,
		animated: false,
		code: "import { Button } from \"@delacour/native-ui/button\";\nimport { Screen } from \"@delacour/native-ui/screen\";\nimport { type ReactElement, useEffect, useState } from \"react\";\n\n/** How long the retry spins before failing again. */\nconst RETRY_MS = 1400;\n\n/**\n * `Screen.Loading` and `Screen.Error`, returned in place of a route's content.\n *\n * Neither takes an `onBack` here: this is a root screen, and omitting the\n * handler renders the navbar without a back control rather than dropping the\n * bar — which is what keeps the frame from shifting between the three states.\n *\n * Nesting either inside another `Screen` is safe too. The provider passes the\n * outer context through rather than shadowing it.\n */\nexport function Demo(): ReactElement {\n\tconst [isLoading, setLoading] = useState(false);\n\n\tuseEffect(() => {\n\t\tif (!isLoading) return;\n\t\tconst timer = setTimeout(() => setLoading(false), RETRY_MS);\n\t\treturn () => clearTimeout(timer);\n\t}, [isLoading]);\n\n\tif (isLoading) return <Screen.Loading title=\"Inbox\" />;\n\n\treturn (\n\t\t<Screen.Error message=\"The request timed out before the server answered. Check your connection and try again.\">\n\t\t\t<Button haptic=\"medium\" onPress={() => setLoading(true)} size=\"sm\" testID=\"try-again\">\n\t\t\t\tTry again\n\t\t\t</Button>\n\t\t</Screen.Error>\n\t);\n}\n",
		light: { poster: "/previews/screen/loading-and-error/light.png?v=6d606f1aaf6c" },
		dark: { poster: "/previews/screen/loading-and-error/dark.png?v=6d606f1aaf6c" },
		sourceHash: "6d606f1aaf6c",
		capturedAt: "2026-08-26T19:26:50.772Z",
		device: "iPhone 17 Pro · iOS 26.3",
	},
